// Normalize direct WF04/WF98 invocation and protected webhook input
// into one plain payload object.

const input = $json ?? {};

const payload =
  input.body !== null &&
  typeof input.body === 'object' &&
  !Array.isArray(input.body)
    ? input.body
    : input;

return {
  json: payload,
};

// Validate the authoritative WF05 invocation contract.

const input = $json ?? {};

const UUID_PATTERN =
  /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;

function requireUuid(value, fieldName) {
  if (typeof value !== 'string') {
    throw new Error(
      `${fieldName} must be a UUID string`,
    );
  }

  const normalized =
    value.trim().toLowerCase();

  if (!UUID_PATTERN.test(normalized)) {
    throw new Error(
      `${fieldName} must be a valid UUID`,
    );
  }

  return normalized;
}

function optionalUuid(value, fieldName) {
  if (
    value === null ||
    value === undefined ||
    String(value).trim() === ''
  ) {
    return null;
  }

  return requireUuid(
    value,
    fieldName,
  );
}

const triggerSource = String(
  input.trigger_source ?? '',
)
  .trim()
  .toLowerCase();

if (
  triggerSource !== 'wf04' &&
  triggerSource !== 'wf98'
) {
  throw new Error(
    'trigger_source must be wf04 or wf98',
  );
}

const caseId = requireUuid(
  input.case_id,
  'case_id',
);

const correlationId = requireUuid(
  input.correlation_id,
  'correlation_id',
);

const clientId = optionalUuid(
  input.client_id,
  'client_id',
);

const acceptedSubmissionId = optionalUuid(
  input.accepted_submission_id,
  'accepted_submission_id',
);

const externalOperationId = optionalUuid(
  input.external_operation_id,
  'external_operation_id',
);

if (triggerSource === 'wf04') {
  if (
    clientId === null ||
    acceptedSubmissionId === null
  ) {
    throw new Error(
      'WF04 invocation requires client_id and accepted_submission_id',
    );
  }

  if (externalOperationId !== null) {
    throw new Error(
      'WF04 invocation must not contain external_operation_id',
    );
  }
}

if (triggerSource === 'wf98') {
  if (externalOperationId === null) {
    throw new Error(
      'WF98 invocation requires external_operation_id',
    );
  }

  if (
    clientId !== null ||
    acceptedSubmissionId !== null
  ) {
    throw new Error(
      'WF98 invocation must not contain WF04 identity fields',
    );
  }
}

return {
  json: {
    case_id: caseId,
    correlation_id: correlationId,
    trigger_source: triggerSource,
    client_id: clientId,
    accepted_submission_id:
      acceptedSubmissionId,
    external_operation_id:
      externalOperationId,
  },
};

// Validate WF05 runtime configuration and construct the context
// used by PostgreSQL preparation and the later provider call.

const input = $json ?? {};

function requireText(value, fieldName) {
  const normalized =
    String(value ?? '').trim();

  if (normalized === '') {
    throw new Error(
      `${fieldName} must not be blank`,
    );
  }

  return normalized;
}

function readInteger(
  name,
  minimum,
  maximum,
) {
  const rawValue = requireText(
    $env[name],
    name,
  );

  const value = Number(rawValue);

  if (
    !Number.isInteger(value) ||
    value < minimum ||
    value > maximum
  ) {
    throw new Error(
      `${name} must be an integer between ${minimum} and ${maximum}`,
    );
  }

  return value;
}

const providerBaseUrl = requireText(
  $env.PROVISIONING_API_BASE_URL,
  'PROVISIONING_API_BASE_URL',
).replace(/\/+$/, '');

let parsedProviderUrl;

try {
  parsedProviderUrl =
    new URL(providerBaseUrl);
} catch {
  throw new Error(
    'PROVISIONING_API_BASE_URL must be a valid URL',
  );
}

if (
  parsedProviderUrl.protocol !== 'http:' &&
  parsedProviderUrl.protocol !== 'https:'
) {
  throw new Error(
    'PROVISIONING_API_BASE_URL must use HTTP or HTTPS',
  );
}

const executionId = requireText(
  $execution.id,
  'execution_id',
);

const leaseSeconds = readInteger(
  'WF05_OPERATION_LEASE_SECONDS',
  1,
  86400,
);

const maxAttempts = readInteger(
  'WF05_OPERATION_MAX_ATTEMPTS',
  1,
  20,
);

let scenario = null;

if (input.trigger_source === 'wf04') {
  scenario = requireText(
    $env.WF05_PROVISIONING_SCENARIO,
    'WF05_PROVISIONING_SCENARIO',
  ).toLowerCase();

  const allowedScenarios =
    new Set([
      'success',
      'retryable_once',
      'retryable_always',
      'terminal',
    ]);

  if (!allowedScenarios.has(scenario)) {
    throw new Error(
      'WF05_PROVISIONING_SCENARIO is invalid',
    );
  }
}

return {
  json: {
    ...input,

    execution_id:
      executionId,

    scenario,

    provider_base_url:
      providerBaseUrl,

    lease_seconds:
      leaseSeconds,

    max_attempts:
      maxAttempts,
  },
};

// Normalize the authoritative PostgreSQL WF05 preparation result
// before routing to provider call, no-op, or WF99 intervention.

const row = $json ?? {};

function isPlainObject(value) {
  return (
    value !== null &&
    typeof value === 'object' &&
    !Array.isArray(value)
  );
}

function requireText(value, fieldName) {
  const normalized =
    String(value ?? '').trim();

  if (normalized === '') {
    throw new Error(
      `${fieldName} must not be blank`,
    );
  }

  return normalized;
}

function optionalText(value) {
  if (
    value === null ||
    value === undefined
  ) {
    return null;
  }

  const normalized =
    String(value).trim();

  return normalized === ''
    ? null
    : normalized;
}

if (!isPlainObject(row.input_context)) {
  throw new Error(
    'input_context must be a JSON object',
  );
}

if (!isPlainObject(row.preparation_result)) {
  throw new Error(
    'preparation_result must be a JSON object',
  );
}

const inputContext =
  row.input_context;

const result =
  row.preparation_result;

const preparationOutcome = requireText(
  result.preparation_outcome,
  'preparation_outcome',
);

let nextAction;

if (
  preparationOutcome ===
  'ready_to_call'
) {
  nextAction =
    'call_provider';

} else if (
  new Set([
    'already_provisioned',
    'busy',
    'not_due',
    'not_required',
  ]).has(preparationOutcome)
) {
  nextAction =
    'no_action';

} else {
  nextAction =
    'operator_intervention_required';
}

let providerUrl = null;

if (nextAction === 'call_provider') {
  const providerBaseUrl = requireText(
    inputContext.provider_base_url,
    'provider_base_url',
  ).replace(/\/+$/, '');

  const endpointPath = requireText(
    result.endpoint_path,
    'endpoint_path',
  );

  providerUrl =
    providerBaseUrl +
    (
      endpointPath.startsWith('/')
        ? endpointPath
        : `/${endpointPath}`
    );

  requireText(
    result.operation_id,
    'operation_id',
  );

  requireText(
    result.lease_owner,
    'lease_owner',
  );

  requireText(
    result.idempotency_key,
    'idempotency_key',
  );

  requireText(
    result.company_name,
    'company_name',
  );

  requireText(
    result.company_identifier,
    'company_identifier',
  );

  requireText(
    result.scenario,
    'scenario',
  );
}

return {
  json: {
    ...inputContext,
    ...result,

    workflow:
      'WF05',

    next_action:
      nextAction,

    provider_url:
      providerUrl,

    error_code:
      optionalText(result.error_code),
  },
};

// Return a controlled idempotent WF05 no-action result.

const input = $json ?? {};

if (input.next_action !== 'no_action') {
  throw new Error(
    'Return Provisioning No Action Result received an invalid next action',
  );
}

return {
  json: {
    workflow:
      'WF05',

    result:
      'no_action',

    preparation_outcome:
      input.preparation_outcome ?? null,

    operation_claim_outcome:
      input.operation_claim_outcome ?? null,

    case_id:
      input.case_id ?? null,

    correlation_id:
      input.correlation_id ?? null,

    operation_id:
      input.operation_id ?? null,

    external_client_id:
      input.external_client_id ?? null,

    case_state:
      input.case_state ?? null,
  },
};
